sp_widget.client_script:
function initializeWidget() {
  var approveBtn = document.getElementById('approveBtn');
  var rejectBtn = document.getElementById('rejectBtn');
  var modifyBtn = document.getElementById('modifyBtn');
  var consultBtn = document.getElementById('consultBtn');
  var overlay = document.getElementById('successOverlay');
  var iconContainer = document.getElementById('iconContainer');
  var resultText = document.getElementById('resultText');
  var resultMessage = document.getElementById('resultMessage');

  if (!approveBtn || !overlay) return;

  // Function to create SVG icons
  function createApproveIcon() {
    return `
      <svg class="result-icon-svg" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
        <circle class="approve-circle-bg" cx="60" cy="60" r="54" fill="none" />
        <path class="approve-tick" d="M40,60 L54,74 L82,46" />
      </svg>
    `;
  }

  function createRejectIcon() {
    return `
      <svg class="result-icon-svg" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
        <circle class="reject-circle-bg" cx="60" cy="60" r="54" fill="none" />
        <path class="reject-cross" d="M40,40 L80,80 M80,40 L40,80" />
      </svg>
    `;
  }

  function createModifyIcon() {
    return `
      <svg class="result-icon-svg" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
        <circle class="modify-circle-bg" cx="60" cy="60" r="54" fill="none" />
        <path class="modify-pencil" d="M30,75 L45,90 L85,50 L70,35 L30,75 Z M70,35 L85,50" />
        <circle cx="70" cy="50" r="4" fill="#f59e0b" />
      </svg>
    `;
  }

  function createConsultIcon() {
    return `
      <svg class="result-icon-svg" viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg">
        <circle class="consult-circle-bg" cx="60" cy="60" r="54" fill="none" />
        <circle cx="60" cy="45" r="8" fill="#3b82f6" />
        <path class="consult-info" d="M60,58 L60,85 M60,68 L72,68 M60,68 L48,68" stroke="#3b82f6" stroke-width="5" fill="none" stroke-linecap="round" />
      </svg>
    `;
  }

  function showResult(type, title, message, iconHTML) {
    if (overlay.classList.contains('active')) {
      // Remove active class to reset animations
      overlay.classList.remove('active');
      // Small delay to allow reset
      setTimeout(function() {
        showResultInternal(type, title, message, iconHTML);
      }, 100);
      return;
    }
    showResultInternal(type, title, message, iconHTML);
  }

  function showResultInternal(type, title, message, iconHTML) {
    // Set icon
    iconContainer.innerHTML = iconHTML;

    // Set text with color class
    resultText.textContent = title;
    resultText.className = 'result-text ' + type;

    // Set message
    resultMessage.textContent = message;

    // Show overlay
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';

    // Auto-close after 3 seconds
    if (window._timeoutId) {
      clearTimeout(window._timeoutId);
    }
    window._timeoutId = setTimeout(function() {
      if (overlay.classList.contains('active')) {
        overlay.classList.remove('active');
        document.body.style.overflow = '';
      }
    }, 3200);
  }

  // Button click handlers
  function handleApprove() {
    var patient = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Patient';
    showResult('approved', 'Approved', 'Refill request for ' + patient + ' has been approved', createApproveIcon());
    console.log('✅ Approved: Refill request approved');
  }

  function handleReject() {
    var patient = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Patient';
    showResult('rejected', 'Rejected', 'Refill request for ' + patient + ' has been rejected', createRejectIcon());
    console.log('❌ Rejected: Refill request rejected');
  }

  function handleModify() {
    var patient = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Patient';
    showResult('modified', 'Modify', 'Refill request for ' + patient + ' has been modified', createModifyIcon());
    console.log('✎ Modified: Refill request modified');
  }

  function handleConsult() {
    var patient = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Patient';
    showResult('consulted', 'Consult', 'Consultation requested for ' + patient + "'s refill", createConsultIcon());
    console.log('💬 Consult: Consultation requested');
  }

  // Attach event listeners
  function attachListener(btn, handler) {
    var newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);
    newBtn.addEventListener('click', handler);
    return newBtn;
  }

  var newApprove = attachListener(approveBtn, handleApprove);
  var newReject = attachListener(rejectBtn, handleReject);
  var newModify = attachListener(modifyBtn, handleModify);
  var newConsult = attachListener(consultBtn, handleConsult);

  // Close overlay on background click
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) {
      overlay.classList.remove('active');
      document.body.style.overflow = '';
      if (window._timeoutId) {
        clearTimeout(window._timeoutId);
        window._timeoutId = null;
      }
    }
  });

  // Close with Escape key
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && overlay.classList.contains('active')) {
      overlay.classList.remove('active');
      document.body.style.overflow = '';
      if (window._timeoutId) {
        clearTimeout(window._timeoutId);
        window._timeoutId = null;
      }
    }
  });
}

// Initialize
if (window.frameElement && window.frameElement.getAttribute('data-sn-widget')) {
  initializeWidget();
} else {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeWidget);
  } else {
    initializeWidget();
  }
}

sp_widget.css:
/* Main Container with Sidebar */
.trackmed-container {
  display: flex;
  min-height: 100vh;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: #f5f7fa;
}

/* Sidebar Styles */
.sidebar {
  width: 300px;
  background: #0b2b3b;
  color: white;
  position: fixed;
  height: 100vh;
  overflow-y: auto;
  box-shadow: 2px 0 12px rgba(0, 0, 0, 0.1);
}

.sidebar-header {
  padding: 1.8rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 1rem;
}

.sidebar-header h2 {
  font-size: 2rem;
  font-weight: 700;
  margin: 0;
  color: white;
}

.sidebar-header h2 span {
  color: #2ecc71;
  font-weight: 400;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.9rem 1.5rem;
  color: rgba(255, 255, 255, 0.8);
  text-decoration: none;
  transition: all 0.2s ease;
  font-size: 1rem;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

.nav-item.active {
  background: #1e4a5f;
  color: white;
  border-left: 3px solid #2ecc71;
}

.nav-icon {
  font-size: 1.2rem;
  width: 24px;
}

/* Main Content Area */
.main-content {
  flex: 1;
  margin-left: 300px;
  padding: 2rem;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

/* Widget Styles */
.trackmed-widget {
  max-width: 1000px;
  width: 100%;
  background: #ffffff;
  border-radius: 2rem;
  box-shadow: 0 25px 45px -12px rgba(0, 0, 0, 0.25);
  overflow: hidden;
}

.brand-header {
  background: #0b2b3b;
  padding: 1.5rem 2.5rem;
  color: white;
}

.brand-header h1 {
  font-size: 1.8rem;
  font-weight: 600;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.brand-header h1 span {
  font-weight: 400;
  font-size: 0.9rem;
  background: #2c5a6e;
  padding: 0.2rem 0.7rem;
  border-radius: 40px;
}

.refill-badge {
  background: rgba(255, 255, 255, 0.15);
  display: inline-block;
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.3rem 1rem;
  border-radius: 30px;
  margin-top: 0.7rem;
}

.request-content {
  padding: 2rem 2.5rem;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #edf2f7;
  padding: 1.2rem 0;
}

.info-label {
  font-weight: 600;
  color: #1e2a3e;
  font-size: 1rem;
  width: 30%;
}

.info-value {
  width: 70%;
  color: #0f2b3d;
  font-weight: 500;
}

.blue-highlight {
  background: #e8f0fe;
  border-radius: 0.75rem;
  transition: all 0.2s ease;
}

.blue-highlight:focus-within {
  background: #d9e6f7;
  box-shadow: 0 0 0 2px rgba(15, 107, 79, 0.2);
}

.blue-field {
  width: 100%;
  padding: 0.9rem 1rem;
  border: 2px solid #4a90e2;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-family: inherit;
  background: white;
  transition: all 0.2s ease;
}

.blue-field:focus {
  outline: none;
  border-color: #0f6b4f;
  box-shadow: 0 0 0 3px rgba(15, 107, 79, 0.1);
}

.blue-field:hover {
  border-color: #2c6eb0;
}

.status-select {
  cursor: pointer;
  background: white;
}

.editable-textarea {
  width: 100%;
  padding: 0.9rem 1rem;
  border: 2px solid #4a90e2;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-family: inherit;
  resize: vertical;
  min-height: 120px;
  background: white;
  transition: all 0.2s ease;
}

.editable-textarea:focus {
  outline: none;
  border-color: #0f6b4f;
  box-shadow: 0 0 0 3px rgba(15, 107, 79, 0.1);
}

.notes-section {
  margin-top: 1.5rem;
  background: #f8fafc;
  padding: 1.2rem 1.5rem;
  border-radius: 1rem;
  border-left: 4px solid #2b7a62;
}

.notes-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  font-weight: 600;
  color: #2b6a54;
  margin-bottom: 0.7rem;
}

/* Action Buttons - 4 Button Layout */
.action-buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  padding: 1.5rem 2.5rem 2.5rem 2.5rem;
}

.action-btn {
  padding: 1rem 0.5rem;
  border: none;
  border-radius: 1rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: inherit;
}

.btn-icon {
  font-size: 1.2rem;
  font-weight: 700;
}

/* Approve Button */
.approve-btn {
  background: #0f6b4f;
  color: white;
  box-shadow: 0 4px 12px rgba(15, 107, 79, 0.3);
}

.approve-btn:hover {
  background: #0a5a42;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(15, 107, 79, 0.4);
}

/* Reject Button */
.reject-btn {
  background: #dc2626;
  color: white;
  box-shadow: 0 4px 12px rgba(220, 38, 38, 0.3);
}

.reject-btn:hover {
  background: #b91c1c;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(220, 38, 38, 0.4);
}

/* Modify Button */
.modify-btn {
  background: #f59e0b;
  color: white;
  box-shadow: 0 4px 12px rgba(245, 158, 11, 0.3);
}

.modify-btn:hover {
  background: #d97706;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(245, 158, 11, 0.4);
}

/* Consult Button */
.consult-btn {
  background: #3b82f6;
  color: white;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
}

.consult-btn:hover {
  background: #2563eb;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(59, 130, 246, 0.4);
}

/* Animation Overlay */
.animation-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2000;
  visibility: hidden;
  opacity: 0;
  transition: visibility 0s, opacity 0.3s ease;
}

.animation-overlay.active {
  visibility: visible;
  opacity: 1;
}

.success-card {
  background: white;
  border-radius: 3rem;
  padding: 3rem 3.5rem;
  text-align: center;
  max-width: 400px;
  width: 90%;
  box-shadow: 0 35px 60px rgba(0, 0, 0, 0.3);
  animation: floatIn 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes floatIn {
  0% {
    opacity: 0;
    transform: scale(0.8) translateY(30px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* Icon Container for Animations */
.icon-container {
  width: 130px;
  height: 130px;
  margin: 0 auto 1.5rem auto;
  position: relative;
}

/* SVG Icons */
.result-icon-svg {
  width: 100%;
  height: 100%;
}

/* Approve - Green Tick */
.approve-circle-bg {
  stroke: #0f6b4f;
  stroke-width: 4;
  fill: none;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: drawCircle 0.6s ease-out forwards;
}

.approve-tick {
  stroke: #0f6b4f;
  stroke-width: 6;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 80;
  stroke-dashoffset: 80;
  animation: drawTick 0.5s ease-out 0.4s forwards;
}

/* Reject - Red Cross */
.reject-circle-bg {
  stroke: #dc2626;
  stroke-width: 4;
  fill: none;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: drawCircle 0.6s ease-out forwards;
}

.reject-cross {
  stroke: #dc2626;
  stroke-width: 6;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: drawCross 0.5s ease-out 0.4s forwards;
}

/* Modify - Pencil/Yellow */
.modify-circle-bg {
  stroke: #f59e0b;
  stroke-width: 4;
  fill: none;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: drawCircle 0.6s ease-out forwards;
}

.modify-pencil {
  stroke: #f59e0b;
  stroke-width: 5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 120;
  stroke-dashoffset: 120;
  animation: drawPencil 0.5s ease-out 0.4s forwards;
}

/* Consult - Blue/Info */
.consult-circle-bg {
  stroke: #3b82f6;
  stroke-width: 4;
  fill: none;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: drawCircle 0.6s ease-out forwards;
}

.consult-info {
  stroke: #3b82f6;
  stroke-width: 5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 80;
  stroke-dashoffset: 80;
  animation: drawInfo 0.5s ease-out 0.4s forwards;
}

/* Animation Keyframes */
@keyframes drawCircle {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes drawTick {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes drawCross {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes drawPencil {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes drawInfo {
  to {
    stroke-dashoffset: 0;
  }
}

/* Result Text */
.result-text {
  font-size: 2.2rem;
  font-weight: 700;
  margin: 0.5rem 0;
}

.result-text.approved {
  color: #0f6b4f;
}

.result-text.rejected {
  color: #dc2626;
}

.result-text.modified {
  color: #f59e0b;
}

.result-text.consulted {
  color: #3b82f6;
}

.extra-message {
  margin-top: 0.8rem;
  font-size: 0.95rem;
  color: #5a6e7c;
}

/* Responsive */
@media (max-width: 768px) {
  .sidebar {
    width: 80px;
  }
  
  .sidebar-header h2 {
    font-size: 1.2rem;
    text-align: center;
  }
  
  .sidebar-header h2 span {
    display: none;
  }
  
  .nav-item span:last-child {
    display: none;
  }
  
  .nav-icon {
    font-size: 1.5rem;
  }
  
  .main-content {
    margin-left: 80px;
  }
  
  .action-buttons {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.8rem;
  }
  
  .info-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }
  
  .info-label, .info-value {
    width: 100%;
  }
}

@media (max-width: 480px) {
  .sidebar {
    display: none;
  }
  
  .main-content {
    margin-left: 0;
  }
  
  .action-buttons {
    grid-template-columns: 1fr;
  }
  
  .success-card {
    padding: 2rem;
  }
}

